import time
from batch import run_all
def job(i, bad=None, exc=None):
    def f():
        time.sleep(0.01)
        if i == bad:
            raise exc(f"job {i} failed")
        return i
    return f
for exc, bad in ((RuntimeError, 0), (ValueError, 3), (KeyError, 5)):
    try:
        got = run_all([job(i, bad, exc) for i in range(6)], workers=2)
    except Exception:
        pass
    else:
        raise AssertionError(("returned although a job raised", exc.__name__, bad, got))
try:
    ok = run_all([job(i) for i in (0, 1, 2)], workers=2)
except Exception as e:
    raise AssertionError(repr(e))
assert sorted(ok) == [0, 1, 2], ok
